.about-nass--conferences-presentations{
  .view-conference-presentation-latest-update {
    .latest-update-header {
      font-weight: 300;
      font-size: 1.65rem;
      text-transform: uppercase;
      padding-top: 2rem;
      padding-bottom: 2rem;
    }
    .views-field-field-date {
      text-transform: uppercase;
      font-size: .75rem;
      letter-spacing: .56px;
      padding-bottom: 1rem;
    }
    .views-field-title {
      font-size: 1.45rem;
      font-weight: 300;
      a {
        color: #000;
      }
    }
    .views-field-field-author {
      font-style: italic;
      font-size: 1rem;
      margin-top: 0.5rem;
    }
    .view-footer h2 {
      padding-top: 2rem;
      padding-bottom: 1rem;
    }
  }
  .bef-exposed-form {
    max-width: 100%;
    position: relative;
    .form--inline > .form-item {
      float: unset;
    }
    .form-item-combine {
      margin-top: 0;
      .usa-label {
        display: none;
      }
      input {
        margin-top: 0;
        border: 2px solid #005EA2;
        border-radius: 4px;
        height: 45px;
        margin-bottom: 3rem;
      }
    }
    .form-actions {
      position: absolute;
      top: 0;
      right: 0;
      #edit-submit-conference-presentation-archive {
        position: absolute;
        right: 2px;
        height: 40px;
        width: 45px;
        top: 2px;
        background-image: url(../img/search-primary.svg);
        display: block;
        background-color: unset;
        background-position: center center;
        background-size: 18px;
        background-repeat: no-repeat;
        margin: 0;
        padding: 0;
        color: #fff0;
      }
    }
    .form-item-field-date-value, .form-item-field-date-and-time-value, .form-item-field-conference-value{
      display: none;
    }
  }
  .conferences{
    padding-left: 2rem;
    .view-grouping {
      .view-grouping-header {
        font-size: 1.35rem;
        padding: 0.75rem;
        background-color: #ddd;
        font-weight: 700;
        margin-top: 1rem;
      }
      .grouping-title {
        padding: 0.75rem;
        font-size: 1.05rem;
        margin-top: 0;
        border-bottom: 1px solid #ddd;
      }
      .conference-pdf {
        padding-bottom: 1rem;
        margin-left: 2rem;
        .views-field-title {
          font-weight: bold;
        }
        .views-field-field-author {
          font-style: italic;
        }
      }
    }
  }
  .attachment-before {
    .views-element-container {
      background-color: #EDEDED;
      padding: 1rem;
      .filter-label {
        font-weight: bold;
        font-size: 13px;   
        margin-bottom: 1rem;
        display: block;
        &:before {
          background: url(../img/usa-icons/filter_alt.svg) no-repeat center/contain;
          display: inline-block;
          height: 1rem;
          width: 1rem;
          content: "";
          vertical-align: middle;
          margin-right: 0.2rem;
        }
      }
    }
    select {
      margin-top: 0;
      border: 2px solid #005ea2;
      border-radius: 4px;
      height: 45px;
      background-image: url('../img/angle-arrow-down-primary.svg');
      background-position: 97% center;
      background-size: 15px;
    }
  }
}

